// Powers the RegWay AI copilot drawer. Loads the caller's firm/fund/
// portfolio-company context from the DB, asks Claude (with the web_search
// tool) to answer grounded in live regulatory sources, and persists the
// exchange to `regway_ai_messages`. With a `conversationId` (generated by the
// drawer per chat) the exchange is saved to that conversation, and its
// earlier turns are sent to the model so follow-ups keep the thread.
//
// Streams the response back as raw Anthropic SSE (text/event-stream) so the
// frontend can render text as it arrives instead of waiting for the full
// reply. The bytes are forwarded unchanged and read on the way past
// (stream.ts) to keep what is saved once the answer ends.
//
// When the answer claims that something applies (or doesn't) to the firm, a
// fund or a company, a check runs after it on the same stream, with step
// labels and a short note (review.ts; CHAT_REVIEW secret, off by default).
//
// The system prompt and the web_search tool definition are marked
// cache_control: ephemeral — both are identical across every message in a
// session, so repeat messages within the cache window are billed at the
// cache rate.
//
// Stop: the browser stops reading and stamps the conversation's stopped_at;
// the function watches for that stamp (conversation.ts watchForStop), since
// a closed connection alone does not reach it. A stopped answer is not saved
// and its check is cancelled.
//
// `refocus` switches what the conversation is about from inside the chat
// (the whole firm, one fund, one company): the conversation's stored scope
// is updated and the model is told on that turn.
//
//   POST /functions/v1/regway-ai-chat   { "message": "...", "conversationId"?: "<uuid>", "context"?: AiContext, "refocus"?: Refocus, "attachment"?: { "name": string, "mimeType": string, "content": string (text) | "base64Data": string (pdf) } }
//   Authorization: Bearer <user session access_token>

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.45.4'
import { AI_FAILURE_MESSAGES, aiFailure, recordFailure, streamClaude } from '../_shared/ai/client.ts'
import { MODEL_FOR } from '../_shared/ai/models.ts'
import { corsHeaders, handleOptions, json } from '../_shared/cors.ts'
import { loadMatchedDevelopments, type MatchScope } from '../_shared/matchedDevelopments.ts'
import type { CompanyRow, FundRow } from '../_shared/relevance.ts'
import { firmRecord } from '../_shared/roles/entityContext.ts'
import { recordUsage } from '../_shared/usage.ts'
import { historyMessages, loadHistory, openConversation, refocusNote, resolveRefocus, watchForStop, type HistoryTurn, type Refocus } from './conversation.ts'
import { sizeProblem, systemPrompt, type AiContext, type Attachment, type EntityRow, type FirmSummary, type UnconfirmedFinding } from './prompt.ts'
import { chatReviewEnabled, checkAnswer } from './review.ts'
import { AnswerCollector, sseEvent } from './stream.ts'

const MODEL = MODEL_FOR.chat

Deno.serve(async (req) => {
  const preflight = handleOptions(req)
  if (preflight) return preflight

  try {
    const body = (await req.json()) as { message?: string; attachment?: Attachment; context?: AiContext; conversationId?: string; refocus?: Refocus }
    const { message, attachment, conversationId } = body
    // When the question was asked: saved with it, so it sorts before its
    // answer (a single insert would give both rows the same created_at).
    const askedAt = new Date()
    let context = body.context
    if (!message) return json({ error: 'message is required' }, 400)
    const tooBig = sizeProblem(message, attachment)
    if (tooBig) return json({ error: tooBig }, 413)

    const authHeader = req.headers.get('Authorization')
    if (!authHeader) return json({ error: 'Missing Authorization header' }, 401)

    const supabase = createClient(
      Deno.env.get('SUPABASE_URL')!,
      Deno.env.get('SUPABASE_ANON_KEY')!,
      { global: { headers: { Authorization: authHeader } } },
    )
    // usage_events has no RLS policies for authenticated users (internal
    // cost telemetry, not firm-scoped data) — needs the service role.
    const admin = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!)

    const {
      data: { user },
    } = await supabase.auth.getUser()
    if (!user) return json({ error: 'Not authenticated' }, 401)

    const { data: membership } = await supabase
      .from('firm_members')
      .select('firm_id, firms(name, hq_location, jurisdictions, profile, profile_meta)')
      .eq('user_id', user.id)
      .single()

    if (!membership) return json({ error: 'No firm associated with this user' }, 404)

    const firm = (membership as unknown as { firms: FirmSummary | null }).firms

    // Before anything is created or spent: a refused message must not
    // leave an empty conversation behind in the user's history.
    const { data: allowed } = await supabase.rpc('check_rate_limit', {
      p_function_name: 'regway-ai-chat',
      p_limit: 30,
      p_window_minutes: 60,
    })
    if (!allowed) return json({ error: 'Rate limit exceeded. Please try again later.' }, 429)

    // Saved conversation: its stored scope wins over the page it was
    // reopened from, and its earlier turns give the model the thread.
    let history: HistoryTurn[] = []
    let startedConversation = false
    let stoppedAt: string | null = null
    if (conversationId) {
      const conversation = await openConversation(supabase, conversationId, membership.firm_id, user.id, message, context)
      if (!conversation) return json({ error: 'Conversation not found' }, 404)
      context = conversation.context ?? undefined
      startedConversation = conversation.created
      stoppedAt = conversation.stoppedAt
      history = await loadHistory(supabase, conversationId)
    }
    const forgetConversation = async () => {
      if (startedConversation) await supabase.from('regway_ai_conversations').delete().eq('id', conversationId)
    }

    let focusNote = ''
    if (body.refocus) {
      const next = await resolveRefocus(supabase, membership.firm_id, body.refocus)
      if (next === null) {
        await forgetConversation()
        return json({ error: 'That fund or company was not found' }, 404)
      }
      context = next
      if (conversationId) await supabase.from('regway_ai_conversations').update({ context: next ?? null }).eq('id', conversationId)
      // Only worth saying once there's an earlier thread to set aside.
      if (history.length) focusNote = refocusNote(next)
    }

    // What RegWay has already matched, narrowed to whatever the chat was
    // opened from (a fund, a company, one regulation), else firm-wide.
    const scope: MatchScope = context ? { type: context.type, id: context.id } : { type: 'firm' }
    const [{ data: funds }, { data: companies }, { data: holdings }, { data: unconfirmed }, matched] = await Promise.all([
      supabase.from('funds').select('id, name, size, structure, jurisdictions, profile, profile_meta').eq('firm_id', membership.firm_id).order('name'),
      supabase.from('portfolio_companies').select('id, name, hq_location, sectors, regions, offerings, profile, profile_meta').eq('firm_id', membership.firm_id).order('name'),
      supabase.from('fund_holdings').select('fund_id, portfolio_company_id').eq('firm_id', membership.firm_id),
      // Web research the firm has not confirmed: for the chat only, marked.
      supabase.from('firm_findings').select('scope, entity_id, field, value, source_url').eq('firm_id', membership.firm_id).eq('status', 'pending').order('created_at'),
      loadMatchedDevelopments(supabase, membership.firm_id, firm?.name ?? 'the firm', scope),
    ])

    const system = systemPrompt({
      firm,
      funds: (funds ?? []) as EntityRow[],
      companies: (companies ?? []) as EntityRow[],
      holdings: holdings ?? [],
      matched,
      scope,
      context,
      unconfirmed: (unconfirmed ?? []) as UnconfirmedFinding[],
    })

    // Text attachments (.txt/.md) are inlined into the message; a .pdf is
    // sent as a native Anthropic `document` content block — no separate
    // parsing needed. Not persisted anywhere; scoped to this one turn.
    const userContent: unknown[] = []
    if (attachment?.base64Data) {
      userContent.push({ type: 'document', source: { type: 'base64', media_type: attachment.mimeType || 'application/pdf', data: attachment.base64Data } })
    }
    const textWithAttachment = focusNote + (attachment?.content ? `${message}\n\n--- Attached file: ${attachment.name} ---\n${attachment.content}` : message)
    userContent.push({ type: 'text', text: textWithAttachment })

    let anthropicRes: Response
    try {
      anthropicRes = await streamClaude({
        model: MODEL,
        max_tokens: 4096,
        system: [{ type: 'text', text: system, cache_control: { type: 'ephemeral' } }],
        tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: 5, cache_control: { type: 'ephemeral' } }],
        messages: [...historyMessages(history), { role: 'user', content: userContent }],
      }, { spend: { admin, functionName: 'regway-ai-chat', firmId: membership.firm_id } })
    } catch (err) {
      // Nothing was answered, so a conversation this message would have
      // started shouldn't appear in the user's history.
      await forgetConversation()
      await recordFailure({ admin, functionName: 'regway-ai-chat', firmId: membership.firm_id }, MODEL, err)
      // Said plainly ("out of credit"), not as the provider's raw error.
      const failure = aiFailure(err)
      return json({ error: failure ? AI_FAILURE_MESSAGES[failure] : (err as Error).message }, 502)
    }

    const answer = new AnswerCollector()
    const upstream = anthropicRes.body!.getReader()
    const stopReview = new AbortController()
    let persisted = false
    let stopped = false

    // The user pressed stop (the reader went away, or the browser stamped
    // the conversation): the answer and its check stop, and a conversation
    // this message started stays out of the user's history if nothing was
    // saved.
    const stop = async () => {
      if (stopped) return
      stopped = true
      endWatch()
      stopReview.abort()
      await upstream.cancel().catch(() => {})
      if (!persisted) await forgetConversation()
    }
    const endWatch = conversationId ? watchForStop(supabase, conversationId, stoppedAt, () => void stop()) : () => {}

    // Saves the exchange; returns the answer's row id.
    const persist = async (): Promise<string | null> => {
      persisted = true
      const answeredAt = new Date(Math.max(Date.now(), askedAt.getTime() + 1))
      const [saved] = await Promise.all([
        supabase
          .from('regway_ai_messages')
          .insert([
            { firm_id: membership.firm_id, user_id: user.id, conversation_id: conversationId ?? null, role: 'user', content: message, created_at: askedAt.toISOString() },
            { firm_id: membership.firm_id, user_id: user.id, conversation_id: conversationId ?? null, role: 'assistant', content: answer.text, citations: answer.citations, created_at: answeredAt.toISOString() },
          ])
          .select('id, role'),
        conversationId
          ? supabase.from('regway_ai_conversations').update({ updated_at: new Date().toISOString() }).eq('id', conversationId)
          : Promise.resolve(),
        recordUsage(admin, { functionName: 'regway-ai-chat', firmId: membership.firm_id, model: MODEL, ...answer.usage }),
      ])
      const rows = (saved as { data: { id: string; role: string }[] | null }).data ?? []
      return rows.find(r => r.role === 'assistant')?.id ?? null
    }

    // After the answer: the check (review.ts), for an answer that makes a
    // claim about the firm's own entities, while someone is still reading.
    const review = async (send: (bytes: Uint8Array) => void, answerId: string | null) => {
      if (!firm || !chatReviewEnabled() || stopped || !answer.text.trim()) return
      try {
        const result = await checkAnswer({
          admin,
          firmId: membership.firm_id,
          record: firmRecord({ firm, funds: (funds ?? []) as unknown as FundRow[], companies: (companies ?? []) as unknown as CompanyRow[] }, holdings ?? []),
          matched: matched.text,
          question: message,
          answer: answer.text,
          citations: answer.citations,
          signal: stopReview.signal,
          emit: event => send(sseEvent(event)),
        })
        if (result && answerId && !stopped) await supabase.from('regway_ai_messages').update({ review: result }).eq('id', answerId)
      } catch (err) {
        console.error('chat answer check failed', (err as Error).message)
      }
    }

    const stream = new ReadableStream<Uint8Array>({
      async pull(controller) {
        const send = (bytes: Uint8Array) => {
          if (stopped) return
          try {
            controller.enqueue(bytes)
          } catch {
            // The reader went away between the check and this write.
          }
        }
        const { done, value } = await upstream.read()
        if (!done) {
          // Forwarded at once and unchanged; read only to keep the record.
          send(value)
          answer.push(value)
          return
        }
        // Stopped before the answer ended: nothing is saved.
        if (!stopped) await review(send, await persist())
        endWatch()
        try {
          controller.close()
        } catch {
          // Already cancelled by the reader.
        }
      },
      async cancel() {
        await stop()
      },
    })

    return new Response(stream, {
      headers: { ...corsHeaders, 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache' },
    })
  } catch (err) {
    return json({ error: (err as Error).message }, 500)
  }
})
